// Full reproduction script for spyOn inherited method issue
import { spyOn } from './src/index.ts'

let passed = 0
let failed = 0

function test(name: string, fn: () => void) {
  try {
    fn()
    console.log(`✓ ${name}`)
    passed++
  } catch (e: any) {
    console.log(`✗ ${name}: ${e.message}`)
    failed++
  }
}

function expect<T>(actual: T) {
  return {
    toBe(expected: T) {
      if (actual !== expected) throw new Error(`Expected ${expected}, got ${actual}`)
    },
    toBeDefined() {
      if (actual === undefined) throw new Error('Expected defined, got undefined')
    },
    toBeUndefined() {
      if (actual !== undefined) throw new Error(`Expected undefined, got ${actual}`)
    },
    not: {
      toThrow() {
        // This is a no-op for the expect chain
      }
    }
  }
}

// Case 1: Getter inherited from parent (1 level up)
test('Getter inherited from parent (1 level)', () => {
  class Parent {
    get v(): string { return 'parent' }
  }
  class Child extends Parent {}

  const child = new Child()
  expect(child.v).toBe('parent')

  const s = spyOn(child, { getter: 'v' }, () => 'mocked')
  expect(child.v).toBe('mocked')

  s.restore()
  expect(child.v).toBe('parent')
})

// Case 2: Getter inherited from grandparent (2 levels up)
test('Getter inherited from grandparent (2 levels)', () => {
  class GrandParent {
    get v(): string { return 'grandparent' }
  }
  class Parent extends GrandParent {}
  class Child extends Parent {}

  const child = new Child()
  expect(child.v).toBe('grandparent')

  const s = spyOn(child, { getter: 'v' }, () => 'mocked')
  expect(child.v).toBe('mocked')

  s.restore()
  expect(child.v).toBe('grandparent')
})

// Case 3: Method inherited from grandparent
test('Method inherited from grandparent (2 levels)', () => {
  class GrandParent {
    greet() { return 'hello from grandparent' }
  }
  class Parent extends GrandParent {}
  class Child extends Parent {}

  const child = new Child()
  expect(child.greet()).toBe('hello from grandparent')

  const s = spyOn(child, 'greet')
  child.greet() // mock it
  s.willCall(() => 'mocked greet')
  expect(child.greet()).toBe('mocked greet')

  s.restore()
  expect(child.greet()).toBe('hello from grandparent')
})

// Case 4: Getter with setter inherited
test('Getter with setter inherited from grandparent', () => {
  class GrandParent {
    _v = 'grandparent'
    get v(): string { return this._v }
    set v(val: string) { this._v = val }
  }
  class Parent extends GrandParent {}
  class Child extends Parent {}

  const child = new Child()
  expect(child.v).toBe('grandparent')

  const s = spyOn(child, { getter: 'v' }, () => 'mocked')
  expect(child.v).toBe('mocked')

  s.restore()
  expect(child.v).toBe('grandparent')
})

// Case 5: Own property still works
test('Own getter still works', () => {
  class MyClass {
    get v(): string { return 'own' }
  }

  const obj = new MyClass()
  expect(obj.v).toBe('own')

  const s = spyOn(obj, { getter: 'v' }, () => 'mocked')
  expect(obj.v).toBe('mocked')

  s.restore()
  expect(obj.v).toBe('own')
})

// Case 6: Setter inherited from grandparent
test('Setter inherited from grandparent', () => {
  class GrandParent {
    _v = 'initial'
    get v(): string { return this._v }
    set v(val: string) { this._v = val }
  }
  class Parent extends GrandParent {}
  class Child extends Parent {}

  const child = new Child()
  expect(child.v).toBe('initial')

  child.v = 'updated'
  expect(child.v).toBe('updated')

  const s = spyOn(child, { setter: 'v' }, (val) => { /* mock */ })
  child.v = 'mocked set'
  // After restore, setting should work again
  s.restore()
  expect(child.v).toBe('mocked set')
})

// Case 7: 3 levels of inheritance
test('Getter inherited 3 levels deep', () => {
  class GreatGrandParent {
    get v(): string { return 'great-grandparent' }
  }
  class GrandParent extends GreatGrandParent {}
  class Parent extends GrandParent {}
  class Child extends Parent {}

  const child = new Child()
  expect(child.v).toBe('great-grandparent')

  const s = spyOn(child, { getter: 'v' }, () => 'mocked')
  expect(child.v).toBe('mocked')

  s.restore()
  expect(child.v).toBe('great-grandparent')
})

console.log(`\n${passed} passed, ${failed} failed`)
process.exit(failed > 0 ? 1 : 0)

