import { describe, test, expect } from "vitest";
import { spyOn, spy } from "../src/index.ts";

describe("spyOn inherited methods - invariants", () => {
  describe("prototype chain depth", () => {
    test("getter from 1 level up (parent)", () => {
      class Parent {
        get v(): string { return "parent"; }
      }
      class Child extends Parent {}

      const child = new Child();
      expect(child.v).toBe("parent");

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBe("parent");
      expect(Object.getOwnPropertyDescriptor(child, "v")).toBeUndefined();
    });

    test("getter from 2 levels up (grandparent)", () => {
      class GrandParent {
        get v(): string { return "grandparent"; }
      }
      class Parent extends GrandParent {}
      class Child extends Parent {}

      const child = new Child();
      expect(child.v).toBe("grandparent");

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBe("grandparent");
      expect(Object.getOwnPropertyDescriptor(child, "v")).toBeUndefined();
    });

    test("getter from 3 levels up (great-grandparent)", () => {
      class GreatGrandParent {
        get v(): string { return "great-grandparent"; }
      }
      class GrandParent extends GreatGrandParent {}
      class Parent extends GrandParent {}
      class Child extends Parent {}

      const child = new Child();
      expect(child.v).toBe("great-grandparent");

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBe("great-grandparent");
      expect(Object.getOwnPropertyDescriptor(child, "v")).toBeUndefined();
    });

    test("method from 2 levels up", () => {
      class GrandParent {
        greet() { return "hello from grandparent"; }
      }
      class Parent extends GrandParent {}
      class Child extends Parent {}

      const child = new Child();
      expect(child.greet()).toBe("hello from grandparent");

      const s = spyOn(child, "greet");
      s.willCall(() => "mocked greet");
      expect(child.greet()).toBe("mocked greet");

      s.restore();
      expect(child.greet()).toBe("hello from grandparent");
      expect(Object.getOwnPropertyDescriptor(child, "greet")).toBeUndefined();
    });
  });

  describe("getter/setter combinations", () => {
    test("getter with setter inherited from grandparent", () => {
      class GrandParent {
        _v = "grandparent";
        get v(): string { return this._v; }
        set v(val: string) { this._v = val; }
      }
      class Parent extends GrandParent {}
      class Child extends Parent {}

      const child = new Child();
      expect(child.v).toBe("grandparent");

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBe("grandparent");
    });

    test("setter inherited from grandparent", () => {
      class GrandParent {
        _v = "initial";
        get v(): string { return this._v; }
        set v(val: string) { this._v = val; }
      }
      class Parent extends GrandParent {}
      class Child extends Parent {}

      const child = new Child();
      expect(child.v).toBe("initial");

      let setterCalledWith: string | undefined;
      const s = spyOn(child, { setter: "v" }, (val) => { setterCalledWith = val; });

      child.v = "test";
      expect(setterCalledWith).toBe("test");

      s.restore();
      child.v = "restored";
      expect(child.v).toBe("restored");
    });

    test("own getter still works correctly", () => {
      class MyClass {
        get v(): string { return "own"; }
      }

      const obj = new MyClass();
      expect(obj.v).toBe("own");

      const s = spyOn(obj, { getter: "v" }, () => "mocked");
      expect(obj.v).toBe("mocked");

      s.restore();
      expect(obj.v).toBe("own");
    });
  });

  describe("multiple spy/restore cycles", () => {
    test("can spy and restore multiple times on inherited getter", () => {
      class GrandParent {
        get v(): string { return "original"; }
      }
      class Parent extends GrandParent {}

      const child = new Parent();

      // First cycle
      const s1 = spyOn(child, { getter: "v" }, () => "mock1");
      expect(child.v).toBe("mock1");
      s1.restore();
      expect(child.v).toBe("original");

      // Second cycle
      const s2 = spyOn(child, { getter: "v" }, () => "mock2");
      expect(child.v).toBe("mock2");
      s2.restore();
      expect(child.v).toBe("original");
    });
  });

  describe("concurrent spy operations", () => {
    test("spy on different inherited properties simultaneously", () => {
      class GrandParent {
        get a(): string { return "a-original"; }
        get b(): string { return "b-original"; }
      }
      class Parent extends GrandParent {}

      const child = new Parent();

      const s1 = spyOn(child, { getter: "a" }, () => "a-mocked");
      const s2 = spyOn(child, { getter: "b" }, () => "b-mocked");

      expect(child.a).toBe("a-mocked");
      expect(child.b).toBe("b-mocked");

      s1.restore();
      expect(child.a).toBe("a-original");
      expect(child.b).toBe("b-mocked");

      s2.restore();
      expect(child.a).toBe("a-original");
      expect(child.b).toBe("b-original");
    });
  });

  describe("edge cases", () => {
    test("spy on inherited getter with undefined return", () => {
      class GrandParent {
        get v(): string | undefined { return undefined; }
      }
      class Child extends GrandParent {}

      const child = new Child();
      expect(child.v).toBeUndefined();

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBeUndefined();
    });

    test("spy on inherited getter that returns null", () => {
      class GrandParent {
        get v(): string | null { return null; }
      }
      class Child extends GrandParent {}

      const child = new Child();
      expect(child.v).toBeNull();

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBeNull();
    });

    test("spy on inherited getter that returns an object", () => {
      const originalObj = { nested: "value" };
      class GrandParent {
        get v(): object { return originalObj; }
      }
      class Child extends GrandParent {}

      const child = new Child();
      expect(child.v).toBe(originalObj);

      const mockObj = { mocked: true };
      const s = spyOn(child, { getter: "v" }, () => mockObj);
      expect(child.v).toBe(mockObj);

      s.restore();
      expect(child.v).toBe(originalObj);
    });

    test("willCall works on inherited getter spy", () => {
      class GrandParent {
        get v(): string { return "original"; }
      }
      class Child extends GrandParent {}

      const child = new Child();
      const s = spyOn(child, { getter: "v" }, () => "first mock");
      expect(child.v).toBe("first mock");

      s.willCall(() => "second mock");
      expect(child.v).toBe("second mock");

      s.restore();
      expect(child.v).toBe("original");
    });

    test("getOriginal works on inherited getter spy", () => {
      class GrandParent {
        get v(): string { return "original"; }
      }
      class Child extends GrandParent {}

      const child = new Child();
      const s = spyOn(child, { getter: "v" }, () => "mocked");

      const original = s.getOriginal();
      expect(original).toBeDefined();

      s.restore();
      expect(child.v).toBe("original");
    });

    test("inheritance with overridden getter in middle class", () => {
      class GrandParent {
        get v(): string { return "grandparent"; }
      }
      class Parent extends GrandParent {
        get v(): string { return "parent"; }
      }
      class Child extends Parent {}

      const child = new Child();
      expect(child.v).toBe("parent"); // Should get parent's getter

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBe("parent"); // Should restore to parent's getter
    });
  });

  describe("mixed own and inherited", () => {
    test("own property takes precedence over inherited", () => {
      class GrandParent {
        get v(): string { return "grandparent"; }
      }
      class Child extends GrandParent {
        get v(): string { return "child"; }
      }

      const child = new Child();
      expect(child.v).toBe("child");

      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      s.restore();
      expect(child.v).toBe("child");
    });

    test("adding own property after spy on inherited", () => {
      class GrandParent {
        get v(): string { return "grandparent"; }
      }
      class Child extends GrandParent {}

      const child = new Child();
      const s = spyOn(child, { getter: "v" }, () => "mocked");
      expect(child.v).toBe("mocked");

      // This shouldn't affect the spy
      Object.defineProperty(child, "v", { value: "own", configurable: true });

      s.restore();
      // After restore, the own property we added should still be there
      expect(child.v).toBe("own");
    });
  });
});

